#include <cstdio>
static float seenTime,seenSpeed;static int calls;static void Dispatch(float t,float s){seenTime=t;seenSpeed=s;++calls;}static void Run(float t,float s){for(;24.0f<=t;t-=24.0f){}Dispatch(t/24.0f,s);}static bool Near(float a,float b){float d=a-b;return d<0?-d<0.0001f:d<0.0001f;}int main(){Run(25.0f,3.5f);if(calls!=1||!Near(seenTime,1.0f/24.0f)||!Near(seenSpeed,3.5f))return 1;Run(72.0f,-2.0f);if(calls!=2||!Near(seenTime,0.0f)||!Near(seenSpeed,-2.0f))return 2;Run(-3.0f,9.0f);if(calls!=3||!Near(seenTime,-0.125f)||!Near(seenSpeed,9.0f))return 3;std::printf("FAST_FORWARD_TIME_PASS\n");return 0;}